/**
 * Unicode primitives that mirror CPython's character classification.
 *
 * Only the pieces the migrated script depends on are modelled:
 *   - whitespace recognition as used by `int()` when stripping its argument
 *   - decimal digit values (so `int('٤٢')` behaves like CPython)
 *   - printability, which drives `repr()` escaping
 */

/**
 * CPython's `Py_UNICODE_ISSPACE` delegates to the C-locale `Py_ISSPACE` for
 * code points below 128, so the ASCII set is exactly these six characters.
 * Notably \x1c-\x1f are *not* included even though `str.isspace()` accepts
 * them, which is why `int('\x1f5')` raises.
 */
const ASCII_SPACE = new Set(['\t', '\n', '\v', '\f', '\r', ' ']);

/** Code points >= 128 flagged as whitespace by CPython's Unicode table. */
const NON_ASCII_SPACE = new Set([
  0x0085, 0x00a0, 0x1680,
  0x2000, 0x2001, 0x2002, 0x2003, 0x2004, 0x2005,
  0x2006, 0x2007, 0x2008, 0x2009, 0x200a,
  0x2028, 0x2029, 0x202f, 0x205f, 0x3000,
]);

const DECIMAL_DIGIT = /^\p{Nd}$/u;
const NON_PRINTABLE = /^[\p{C}\p{Z}]$/u;

/** True when `ch` is whitespace for the purposes of `int()`/`float()`. */
export function isPySpace(ch) {
  const cp = ch.codePointAt(0);
  return cp < 128 ? ASCII_SPACE.has(ch) : NON_ASCII_SPACE.has(cp);
}

function isDecimalDigitCodePoint(cp) {
  if (cp < 0 || cp > 0x10ffff) return false;
  return DECIMAL_DIGIT.test(String.fromCodePoint(cp));
}

/**
 * Numeric value of any Unicode decimal digit, or -1 when `ch` is not one.
 *
 * Unicode guarantees decimal digits appear as complete, ascending runs of ten
 * starting at the script's zero, so walking back to the start of the run and
 * taking the offset modulo ten yields the value. The modulo matters for blocks
 * that pack several digit sets back to back (e.g. the mathematical alphanumeric
 * digits at U+1D7CE..U+1D7FF).
 */
export function decimalDigitValue(ch) {
  const cp = ch.codePointAt(0);
  if (cp >= 0x30 && cp <= 0x39) return cp - 0x30;
  if (!isDecimalDigitCodePoint(cp)) return -1;
  let offset = 0;
  while (offset < 128 && isDecimalDigitCodePoint(cp - offset - 1)) offset += 1;
  return offset % 10;
}

/**
 * Mirrors `str.isprintable()` for a single character: everything outside the
 * Other and Separator categories is printable, plus the plain ASCII space.
 */
export function isPyPrintable(ch) {
  return ch === ' ' || !NON_PRINTABLE.test(ch);
}

