/**
 * Python-shaped exception types.
 *
 * Each carries the name CPython would print on the last line of a traceback so
 * the traceback renderer stays generic.
 */

export class PyError extends Error {
  constructor(pyName, message) {
    super(message);
    this.name = pyName;
    this.pyName = pyName;
    this.pyMessage = message;
  }
}

export class PyValueError extends PyError {
  constructor(message) {
    super('ValueError', message);
  }
}

export class PyTypeError extends PyError {
  constructor(message) {
    super('TypeError', message);
  }
}

export function isPyError(err) {
  return err instanceof PyError;
}

