/**
 * Insertion-ordered mapping with Python's key identity rules.
 *
 * Two details matter for faithful output:
 *   1. iteration follows first-insertion order (CPython dicts since 3.7);
 *   2. keys that compare equal share a slot, and the *first* key object is the
 *      one kept — so `{False: [...]}` stays `False` even if `0` shows up later.
 */

import { pyRepr } from './repr.mjs';

/** Canonical lookup token implementing Python's `==`/`hash` for our key types. */
function canonicalKey(key) {
  if (key === null || key === undefined) return 'None';
  switch (typeof key) {
    case 'boolean':
      // hash(False) == hash(0) and False == 0, so booleans live in int space.
      return `int:${key ? 1 : 0}`;
    case 'bigint':
      return `int:${key}`;
    case 'number':
      return Number.isInteger(key) ? `int:${BigInt(key)}` : `float:${key}`;
    case 'string':
      return `str:${key}`;
    default:
      return key;
  }
}

export class PyDict {
  #slots = new Map();

  get size() {
    return this.#slots.size;
  }

  has(key) {
    return this.#slots.has(canonicalKey(key));
  }

  get(key, fallback = undefined) {
    const slot = this.#slots.get(canonicalKey(key));
    return slot === undefined ? fallback : slot.value;
  }

  set(key, value) {
    const token = canonicalKey(key);
    const slot = this.#slots.get(token);
    if (slot === undefined) this.#slots.set(token, { key, value });
    else slot.value = value;
    return this;
  }

  /** `dict.setdefault`: insert `value` only when the key is absent. */
  setdefault(key, value) {
    const token = canonicalKey(key);
    const slot = this.#slots.get(token);
    if (slot !== undefined) return slot.value;
    this.#slots.set(token, { key, value });
    return value;
  }

  *keys() {
    for (const slot of this.#slots.values()) yield slot.key;
  }

  *values() {
    for (const slot of this.#slots.values()) yield slot.value;
  }

  *entries() {
    for (const slot of this.#slots.values()) yield [slot.key, slot.value];
  }

  [Symbol.iterator]() {
    return this.keys();
  }

  toPyRepr() {
    const items = [];
    for (const [key, value] of this.entries()) {
      items.push(`${pyRepr(key)}: ${pyRepr(value)}`);
    }
    return `{${items.join(', ')}}`;
  }
}

