/**
 * `int(str)` with CPython semantics, returning a BigInt so that arbitrarily
 * large literals such as 12345678901234567890 survive the round trip.
 */

import { PyValueError } from './errors.mjs';
import { pyRepr } from './repr.mjs';
import { decimalDigitValue, isPySpace } from './unicode.mjs';

/**
 * Accepted grammar (after stripping surrounding whitespace):
 *
 *   [+-] digit (('_')? digit)*
 *
 * where `digit` is any Unicode decimal digit. Underscores must sit strictly
 * between digits, so '_1', '1_', '1__0' and '+_1' all raise.
 */
export function pyInt(text) {
  const invalid = () => {
    throw new PyValueError(
      `invalid literal for int() with base 10: ${pyRepr(text)}`,
    );
  };

  const chars = Array.from(text);
  let start = 0;
  let end = chars.length;
  while (start < end && isPySpace(chars[start])) start += 1;
  while (end > start && isPySpace(chars[end - 1])) end -= 1;

  let i = start;
  let negative = false;
  if (i < end && (chars[i] === '+' || chars[i] === '-')) {
    negative = chars[i] === '-';
    i += 1;
  }

  let digits = '';
  let previousWasDigit = false;
  for (; i < end; i += 1) {
    const ch = chars[i];
    if (ch === '_') {
      if (!previousWasDigit) invalid();
      previousWasDigit = false;
      continue;
    }
    const value = decimalDigitValue(ch);
    if (value < 0) invalid();
    digits += String(value);
    previousWasDigit = true;
  }
  // Catches an empty body, a bare sign, and a trailing underscore alike.
  if (!previousWasDigit) invalid();

  const magnitude = BigInt(digits);
  return negative ? -magnitude : magnitude;
}

