/**
 * Operators whose Python semantics differ from JavaScript's.
 */

/**
 * Python's `%` takes the sign of the divisor, unlike JavaScript's remainder:
 * `-3 % 2` is 1 in Python but -1 in JavaScript.
 */
export function pyMod(a, b) {
  const remainder = a % b;
  if (remainder === 0n) return 0n;
  return (remainder < 0n) !== (b < 0n) ? remainder + b : remainder;
}

/** Python truthiness for the value shapes handled here. */
export function pyBool(value) {
  if (value === null || value === undefined) return false;
  if (typeof value === 'boolean') return value;
  if (typeof value === 'bigint') return value !== 0n;
  if (typeof value === 'number') return value !== 0 && !Number.isNaN(value);
  if (typeof value === 'string') return value.length > 0;
  if (Array.isArray(value)) return value.length > 0;
  if (typeof value.size === 'number') return value.size > 0;
  return true;
}

/** Python `==` across the numeric types used here (int/bool interoperate). */
export function pyEq(a, b) {
  const numeric = (v) => {
    if (typeof v === 'bigint') return v;
    if (typeof v === 'boolean') return v ? 1n : 0n;
    if (typeof v === 'number' && Number.isInteger(v)) return BigInt(v);
    return null;
  };
  const na = numeric(a);
  const nb = numeric(b);
  if (na !== null && nb !== null) return na === nb;
  return a === b;
}

