/**
 * Terminal width discovery matching `shutil.get_terminal_size()`, which
 * argparse uses to size help output.
 */

const FALLBACK_COLUMNS = 80;

/**
 * COLUMNS wins when it parses to a positive integer; otherwise the real
 * terminal is queried, and a non-tty (pipe, file) falls back to 80.
 */
export function getTerminalColumns() {
  const env = process.env.COLUMNS;
  if (env !== undefined && env !== '') {
    const parsed = Number.parseInt(env, 10);
    if (Number.isInteger(parsed) && parsed > 0) return parsed;
  }
  if (process.stdout.isTTY && process.stdout.columns > 0) {
    return process.stdout.columns;
  }
  return FALLBACK_COLUMNS;
}

