/**
 * The script's own layer: the parser definition, the grouping computation, and
 * the traceback frame that stands in for the Python source line that can raise.
 */

import { ArgumentParser } from './argparse/index.mjs';
import { bucketize } from './boltons/iterutils.mjs';
import { pyInt } from './py/int.mjs';
import { pyEq, pyMod } from './py/operators.mjs';

/**
 * Program name reported in usage/help text. The reference build is a frozen
 * executable, so argparse sees `test5_executable` as `sys.argv[0]`; keeping the
 * same literal makes usage, help and error output byte-identical.
 */
export const PROG = 'test5_executable';

/** Mirrors `parser.add_argument('--a', type=str, required=True, help=...)`. */
export function buildParser() {
  const parser = new ArgumentParser({ prog: PROG });
  parser.addArgument(['--a'], {
    type: (value) => value, // type=str
    required: true,
    help: 'Comma-separated numbers',
  });
  return parser;
}

/**
 * Frame for `numbers = [int(x) for x in args.a.split(',')]` (line 8), whose
 * `int()` call is the only statement in the script that can raise. The carets
 * underline `int(x)` the way CPython's fine-grained locations do.
 */
export const INT_CONVERSION_FRAME = {
  file: 'test5.py',
  line: 8,
  name: '<module>',
  source: "numbers = [int(x) for x in args.a.split(',')]",
  caretAt: "numbers = [".length,
  caretLength: 'int(x)'.length,
};

/** `[int(x) for x in args.a.split(',')]` */
export function parseNumbers(raw) {
  return raw.split(',').map((chunk) => pyInt(chunk));
}

/** The key function: `lambda x: x % 2 == 0` — group by parity. */
export function isEven(value) {
  return pyEq(pyMod(value, 2n), 0n);
}

/** `bucketize(numbers, lambda x: x % 2 == 0)` */
export function groupByParity(numbers) {
  return bucketize(numbers, isEven);
}

