/**
 * Node.js port of test5.py
 *
 *   import argparse
 *   from boltons.iterutils import bucketize
 *
 *   parser = argparse.ArgumentParser()
 *   parser.add_argument('--a', type=str, required=True, help='Comma-separated numbers')
 *   args = parser.parse_args()
 *
 *   numbers = [int(x) for x in args.a.split(',')]
 *   result = bucketize(numbers, lambda x: x % 2 == 0)  # group by parity
 *   print(result)
 *
 * Run: node test5.mjs --a 1,2,3,4,5
 */

import {
  INT_CONVERSION_FRAME,
  buildParser,
  groupByParity,
  parseNumbers,
} from './lib/cli.mjs';
import { isPyError } from './lib/py/errors.mjs';
import { pyPrint } from './lib/py/print.mjs';
import { abortWithTraceback } from './lib/py/traceback.mjs';

function main(argv) {
  const parser = buildParser();
  const args = parser.parseArgs(argv);

  let numbers;
  try {
    numbers = parseNumbers(args.a);
  } catch (err) {
    // An uncaught ValueError: same traceback text and exit status as CPython.
    if (!isPyError(err)) throw err;
    abortWithTraceback([INT_CONVERSION_FRAME], err);
    return;
  }

  const result = groupByParity(numbers);
  pyPrint(result);
}

main(process.argv.slice(2));

