/**
 * Renders an uncaught exception the way the CPython interpreter does, so a
 * failing run of the migrated script produces the same stderr text and the
 * same exit status (1) as the original.
 *
 * Frames are supplied by the caller because JavaScript stack frames carry no
 * knowledge of the Python source they stand in for. Note that the reference
 * build is frozen and therefore ships no `.py` source, so CPython cannot echo
 * the offending line or draw the `^^^^` markers under it — only the location
 * line is printed.
 */

import { writeStderr } from './print.mjs';

/**
 * @typedef {object} PyFrame
 * @property {string} file  value printed after `File`
 * @property {number} line  1-based line number in the Python source
 * @property {string} name  enclosing scope, e.g. '<module>'
 */

export function formatTraceback(frames, exception) {
  const lines = ['Traceback (most recent call last):'];
  for (const frame of frames) {
    lines.push(`  File "${frame.file}", line ${frame.line}, in ${frame.name}`);
  }
  const name = exception.pyName ?? 'Exception';
  const message = exception.pyMessage ?? exception.message;
  lines.push(message ? `${name}: ${message}` : name);
  return lines.join('\n') + '\n';
}

/** Prints the traceback to stderr and terminates with CPython's exit code. */
export function abortWithTraceback(frames, exception) {
  writeStderr(formatTraceback(frames, exception));
  process.exit(1);
}

