/** `_parse_optional`: resolve an argument to [action, optionString, explicitArg]. */
#parseOptional(argString) {
  if (argString === '') return null;
  if (!this.prefixChars.includes(argString[0])) return null;
  if (this.optionStringActions.has(argString)) {
    return [this.optionStringActions.get(argString), argString, null];
  }
  if (argString.length === 1) return null;

  const equals = argString.indexOf('=');
  if (equals >= 0) {
    const optionString = argString.slice(0, equals);
    if (this.optionStringActions.has(optionString)) {
      return [
        this.optionStringActions.get(optionString),
        optionString,
        argString.slice(equals + 1),
      ];
    }
  }

  const candidates = this.#optionTuples(argString);
  if (candidates.length > 1) {
    const options = candidates.map((tuple) => tuple[1]).join(', ');
    this.error(`ambiguous option: ${argString} could match ${options}`);
  }
  if (candidates.length === 1) return candidates[0];

  // Nothing in the parser looks like a negative number, so '-3' is a value.
  if (NEGATIVE_NUMBER.test(argString)) return null;
  if (argString.includes(' ')) return null;
  return [null, argString, null];
}

/** `_get_option_tuples`: abbreviation and bundled-short-option candidates. */
#optionTuples(argString) {
  const result = [];
  const chars = this.prefixChars;
  const isLong = argString.length > 1 &&
    chars.includes(argString[0]) && chars.includes(argString[1]);

  if (isLong) {
    let optionPrefix = argString;
    let explicitArg = null;
    const equals = argString.indexOf('=');
    if (equals >= 0) {
      optionPrefix = argString.slice(0, equals);
      explicitArg = argString.slice(equals + 1);
    }
    for (const [optionString, action] of this.optionStringActions) {
      if (optionString.startsWith(optionPrefix)) {
        result.push([action, optionString, explicitArg]);
      }
    }
  } else {
    const shortOptionPrefix = argString.slice(0, 2);
    const shortExplicitArg = argString.slice(2);
    for (const [optionString, action] of this.optionStringActions) {
      if (optionString === shortOptionPrefix) {
        result.push([action, optionString, shortExplicitArg]);
      } else if (optionString.startsWith(argString)) {
        result.push([action, optionString, null]);
