      if (USAGE_PREFIX.length + this.prog.length <= 0.75 * textWidth) {
        // Short prog: hang the arguments off the end of the program name.
        const indent = ' '.repeat(USAGE_PREFIX.length + this.prog.length + 1);
        if (optParts.length > 0) {
          lines = getLines([this.prog, ...optParts], indent, true);
          lines.push(...getLines(posParts, indent, false));
        } else if (posParts.length > 0) {
          lines = getLines([this.prog, ...posParts], indent, true);
        } else {
          lines = [this.prog];
        }
      } else {
        // Long prog: it gets a line of its own.
        const indent = ' '.repeat(USAGE_PREFIX.length);
        lines = getLines([...optParts, ...posParts], indent, false);
        if (lines.length > 1) {
          lines = [
            ...getLines(optParts, indent, false),
            ...getLines(posParts, indent, false),
          ];
        }
        lines = [this.prog, ...lines];
      }
      usage = lines.join('\n');
    }

    return `${USAGE_PREFIX}${usage}\n\n`;
  }

  formatAction(action) {
    const helpPosition = Math.min(this.actionMaxLength + 2, this.maxHelpPosition);
    const helpWidth = Math.max(this.width - helpPosition, 11);
    const actionWidth = helpPosition - this.currentIndent - 2;
    const header = this.formatActionInvocation(action);
