/**
 * The slice of Python's `textwrap` that argparse's help formatter relies on:
 * greedy wrapping with hyphen-aware word splitting.
 */

const WHITESPACE_RUN = /\s+/;
const LETTER = /[a-zA-Z]/;

/**
 * Splits text into whitespace chunks and word chunks, breaking hyphenated
 * words after the hyphen. Python's `wordsep_re` only breaks a hyphen that is
 * preceded by at least two letters and followed by more letters, which is what
 * turns 'Comma-separated' into ['Comma-', 'separated'].
 */
function splitChunks(text) {
  const chunks = [];
  let index = 0;
  while (index < text.length) {
    const rest = text.slice(index);
    const wsMatch = WHITESPACE_RUN.exec(rest);
    if (wsMatch && wsMatch.index === 0) {
      chunks.push(wsMatch[0]);
      index += wsMatch[0].length;
      continue;
    }
    const wordEnd = wsMatch ? index + wsMatch.index : text.length;
    const word = text.slice(index, wordEnd);
    chunks.push(...splitHyphenated(word));
    index = wordEnd;
  }
  return chunks;
}

function splitHyphenated(word) {
  const pieces = [];
  let start = 0;
  for (let i = 1; i < word.length - 1; i += 1) {
    if (word[i] !== '-') continue;
    const twoLettersBefore =
      i - start >= 2 && LETTER.test(word[i - 1]) && LETTER.test(word[i - 2]);
    const lettersAfter = /^[a-zA-Z]-?[a-zA-Z]/.test(word.slice(i + 1));
    if (twoLettersBefore && lettersAfter) {
      pieces.push(word.slice(start, i + 1));
      start = i + 1;
    }
  }
  pieces.push(word.slice(start));
  return pieces.filter((piece) => piece !== '');
}

/**
 * `textwrap.wrap(text, width)` with argparse's defaults
 * (replace_whitespace/collapsing is done by the caller).
 */
export function wrap(text, width) {
  const effectiveWidth = Math.max(1, width);
  const chunks = splitChunks(text);
  const lines = [];
  let cursor = 0;

  while (cursor < chunks.length) {
    // Leading whitespace on a continuation line is dropped.
    if (lines.length >= 0 && WHITESPACE_RUN.test(chunks[cursor]) &&
        chunks[cursor].trim() === '') {
      cursor += 1;
      continue;
    }
    const current = [];
    let length = 0;
    while (cursor < chunks.length) {
      const chunk = chunks[cursor];
      if (length + chunk.length > effectiveWidth) break;
      current.push(chunk);
      length += chunk.length;
      cursor += 1;
    }
    // break_long_words: a single chunk wider than the line is hard-split.
    if (cursor < chunks.length && chunks[cursor].length > effectiveWidth) {
      const space = effectiveWidth - length;
      if (space > 0) {
        current.push(chunks[cursor].slice(0, space));
        chunks[cursor] = chunks[cursor].slice(space);
      } else if (current.length === 0) {
        current.push(chunks[cursor].slice(0, effectiveWidth));
        chunks[cursor] = chunks[cursor].slice(effectiveWidth);
      }
    }
    // Trailing whitespace is dropped.
    while (current.length > 0 && current[current.length - 1].trim() === '') {
      current.pop();
    }
    if (current.length > 0) lines.push(current.join(''));
  }
  return lines;
}

