/**
 * `repr()` / `str()` for the value shapes this migration produces.
 *
 * Container types opt in by exposing a `toPyRepr()` method, which keeps this
 * module free of imports from the container modules (they import this one).
 */

import { isPyPrintable } from './unicode.mjs';

function hex(cp, width) {
  return cp.toString(16).padStart(width, '0');
}

/** Escapes a character exactly the way CPython's `unicode_repr` does. */
function escapeChar(ch, quote) {
  if (ch === '\\') return '\\\\';
  if (ch === quote) return `\\${quote}`;
  if (ch === '\n') return '\\n';
  if (ch === '\r') return '\\r';
  if (ch === '\t') return '\\t';
  if (isPyPrintable(ch)) return ch;
  const cp = ch.codePointAt(0);
  if (cp < 0x100) return `\\x${hex(cp, 2)}`;
  if (cp < 0x10000) return `\\u${hex(cp, 4)}`;
  return `\\U${hex(cp, 8)}`;
}

/**
 * String repr. CPython prefers single quotes and only switches to double
 * quotes when the text contains a single quote but no double quote.
 */
export function pyReprStr(s) {
  const quote = s.includes("'") && !s.includes('"') ? '"' : "'";
  let out = quote;
  for (const ch of s) out += escapeChar(ch, quote);
  return out + quote;
}

export function pyRepr(value) {
  if (value === null || value === undefined) return 'None';
  if (typeof value === 'boolean') return value ? 'True' : 'False';
  if (typeof value === 'bigint') return value.toString();
  if (typeof value === 'string') return pyReprStr(value);
  if (Array.isArray(value)) return `[${value.map(pyRepr).join(', ')}]`;
  if (typeof value.toPyRepr === 'function') return value.toPyRepr();
  if (typeof value === 'number') {
    return Number.isInteger(value) ? String(value) : String(value);
  }
  return String(value);
}

/**
 * `str()`. For every type used here (bool, int, list, dict) `str` and `repr`
 * coincide, and `print` of a container reprs its members.
 */
export function pyStr(value) {
  return typeof value === 'string' ? value : pyRepr(value);
}

