/**
 * Port of the `boltons.iterutils` helpers used by the script, reconstructed
 * from observed behaviour.
 */

import { PyDict } from '../py/dict.mjs';
import { PyTypeError } from '../py/errors.mjs';
import { pyBool } from '../py/operators.mjs';

function isIterable(value) {
  return value !== null && value !== undefined &&
    typeof value[Symbol.iterator] === 'function';
}

/**
 * Groups the items of `src` into lists keyed by `key(item)`.
 *
 * Keys appear in the order they are first produced, and each bucket keeps the
 * source order of its members — which is what makes the printed dict stable.
 *
 * @param {Iterable} src            values to group
 * @param {Function|string} key     key function (default: truthiness), or an
 *                                  attribute name to read off each value
 * @param {object} [options]
 * @param {Function} [options.valueTransform] applied to each value before it is
 *                                  appended to its bucket
 * @param {Function} [options.keyFilter] buckets are only created for keys this
 *                                  predicate accepts
 * @returns {PyDict} key -> array of values
 */
export function bucketize(src, key = pyBool, { valueTransform = null, keyFilter = null } = {}) {
  if (!isIterable(src)) throw new PyTypeError('expected an iterable');

  let keyFunc;
  if (typeof key === 'function') {
    keyFunc = key;
  } else if (typeof key === 'string') {
    keyFunc = (value) => (
      value !== null && value !== undefined && key in Object(value)
        ? value[key]
        : value
    );
  } else {
    throw new PyTypeError('expected key to be callable or a string');
  }

  if (valueTransform !== null && typeof valueTransform !== 'function') {
    throw new PyTypeError('expected callable value transform function');
  }
  if (keyFilter !== null && typeof keyFilter !== 'function') {
    throw new PyTypeError('expected callable key filter function');
  }

  const result = new PyDict();
  for (const value of src) {
    const bucketKey = keyFunc(value);
    if (keyFilter !== null && !pyBool(keyFilter(bucketKey))) continue;
    const bucket = result.setdefault(bucketKey, []);
    bucket.push(valueTransform === null ? value : valueTransform(value));
  }
  return result;
}

/** Convenience wrapper for the common `bucketize(src, bool)` shape. */
export function partition(src, key = pyBool) {
  return bucketize(src, key);
}

