/**
 * Reimplementation of argparse's `HelpFormatter` for the option shapes used by
 * the migrated script: usage line construction (including the two wrapping
 * strategies CPython picks between) and the aligned option/help columns.
 */

import { wrap } from '../textwrap.mjs';
import { getTerminalColumns } from './terminal.mjs';

const USAGE_PREFIX = 'usage: ';

/**
 * argparse's `part_regexp`: when the usage line has to wrap it is re-split into
 * wrappable pieces. Bracketed/parenthesised groups stay glued together, but
 * anything else breaks on whitespace — which is why a required option and its
 * metavar ('--a A') can end up on two different lines.
 */
const USAGE_PART = /\(.*?\)+(?=\s|$)|\[.*?\]+(?=\s|$)|\S+/g;

function usageParts(text) {
  return text.match(USAGE_PART) ?? [];
}

export class HelpFormatter {
  constructor(prog, { indentIncrement = 2, maxHelpPosition = 24, width = null } = {}) {
    this.prog = prog;
    this.indentIncrement = indentIncrement;
    this.width = (width ?? getTerminalColumns()) - 2;
    // argparse clamps the help column on narrow terminals.
    this.maxHelpPosition = Math.min(
      maxHelpPosition,
      Math.max(this.width - 20, indentIncrement * 2),
    );
    this.currentIndent = 0;
    this.actionMaxLength = 0;
  }

  defaultMetavar(action) {
    return action.optionStrings.length > 0
      ? action.dest.toUpperCase()
      : action.dest;
  }

  /** `_format_args` for the nargs values in play (None / 0). */
  formatArgs(action, metavar) {
    return action.nargs === 0 ? '' : metavar;
  }

  /** How the action appears inside the usage line, e.g. `[-h]`, `--a A`. */
  formatActionUsage(action) {
    let part;
    if (action.optionStrings.length === 0) {
      part = this.formatArgs(action, this.defaultMetavar(action));
    } else {
      const optionString = action.optionStrings[0];
      part = action.nargs === 0
        ? optionString
        : `${optionString} ${this.formatArgs(action, this.defaultMetavar(action))}`;
    }
    return action.required ? part : `[${part}]`;
  }

  /** How the action appears in the options list, e.g. `-h, --help`. */
  formatActionInvocation(action) {
    if (action.optionStrings.length === 0) return this.defaultMetavar(action);
    if (action.nargs === 0) return action.optionStrings.join(', ');
    const args = this.formatArgs(action, this.defaultMetavar(action));
    return `${action.optionStrings.join(', ')} ${args}`;
  }

  /** Records the widest invocation so the help column can be aligned. */
  measureActions(actions) {
    for (const action of actions) {
      const length =
        this.formatActionInvocation(action).length + this.indentIncrement;
      this.actionMaxLength = Math.max(this.actionMaxLength, length);
    }
  }

  formatUsage(actions) {
    const optionals = [];
    const positionals = [];
    for (const action of actions) {
      if (action.optionStrings.length > 0) optionals.push(this.formatActionUsage(action));
      else positionals.push(this.formatActionUsage(action));
    }

    let usage = [this.prog, ...optionals, ...positionals].join(' ');
    const textWidth = this.width - this.currentIndent;

    if (USAGE_PREFIX.length + usage.length > textWidth) {
      const optParts = usageParts(optionals.join(' '));
      const posParts = usageParts(positionals.join(' '));

      const getLines = (parts, indent, isFirstGroup) => {
        const lines = [];
        let line = [];
        let lineLength = (isFirstGroup ? USAGE_PREFIX.length : indent.length) - 1;
        for (const part of parts) {
          if (lineLength + 1 + part.length > textWidth && line.length > 0) {
            lines.push(indent + line.join(' '));
            line = [];
            lineLength = indent.length - 1;
          }
          line.push(part);
          lineLength += 1 + part.length;
        }
        if (line.length > 0) lines.push(indent + line.join(' '));
        if (isFirstGroup && lines.length > 0) {
          lines[0] = lines[0].slice(indent.length);
        }
        return lines;
      };

      let lines;
      if (USAGE_PREFIX.length + this.prog.length <= 0.75 * textWidth) {
        // Short prog: hang the arguments off the end of the program name.
        const indent = ' '.repeat(USAGE_PREFIX.length + this.prog.length + 1);
        if (optParts.length > 0) {
          lines = getLines([this.prog, ...optParts], indent, true);
          lines.push(...getLines(posParts, indent, false));
        } else if (posParts.length > 0) {
          lines = getLines([this.prog, ...posParts], indent, true);
        } else {
          lines = [this.prog];
        }
      } else {
        // Long prog: it gets a line of its own.
        const indent = ' '.repeat(USAGE_PREFIX.length);
        lines = getLines([...optParts, ...posParts], indent, false);
        if (lines.length > 1) {
          lines = [
            ...getLines(optParts, indent, false),
            ...getLines(posParts, indent, false),
          ];
        }
        lines = [this.prog, ...lines];
      }
      usage = lines.join('\n');
    }

    return `${USAGE_PREFIX}${usage}\n\n`;
  }

  formatAction(action) {
    const helpPosition = Math.min(this.actionMaxLength + 2, this.maxHelpPosition);
    const helpWidth = Math.max(this.width - helpPosition, 11);
    const actionWidth = helpPosition - this.currentIndent - 2;
    const header = this.formatActionInvocation(action);
    const indent = ' '.repeat(this.currentIndent);

    const parts = [];
    let indentFirst = 0;
    if (!action.help) {
      parts.push(`${indent}${header}\n`);
    } else if (header.length <= actionWidth) {
      parts.push(`${indent}${header.padEnd(actionWidth)}  `);
    } else {
      parts.push(`${indent}${header}\n`);
      indentFirst = helpPosition;
    }

    if (action.help && action.help.trim() !== '') {
      const text = action.help.replace(/\s+/g, ' ').trim();
      const helpLines = wrap(text, helpWidth);
      parts.push(`${' '.repeat(indentFirst)}${helpLines[0]}\n`);
      for (const line of helpLines.slice(1)) {
        parts.push(`${' '.repeat(helpPosition)}${line}\n`);
      }
    }
    return parts.join('');
  }

  /** `_Section.format_help` for a titled group of actions. */
  formatSection(title, actions) {
    const previousIndent = this.currentIndent;
    this.currentIndent += this.indentIncrement;
    const items = actions.map((action) => this.formatAction(action)).join('');
    this.currentIndent = previousIndent;
    if (items === '') return '';
    const heading = `${' '.repeat(this.currentIndent)}${title}:\n`;
    return `\n${heading}${items}\n`;
  }

  /**
   * `format_help`'s tail: collapse runs of blank lines and end with exactly one
   * trailing newline.
   */
  static normalize(text) {
    if (text === '') return text;
    return text.replace(/\n\n\n+/g, '\n\n').replace(/^\n+|\n+$/g, '') + '\n';
  }
}

