/**
 * The subset of `argparse.ArgumentParser` needed to reproduce the source
 * script's CLI, including the error messages, exit codes and abbreviation
 * matching that argparse provides for free in Python.
 */

import { pyReprStr } from '../py/repr.mjs';
import { writeStderr, writeStdout } from '../py/print.mjs';
import { ArgumentError } from './errors.mjs';
import { HelpFormatter } from './formatter.mjs';

/** argparse's `_negative_number_matcher` (Python's `\d` is Unicode-aware). */
const NEGATIVE_NUMBER = /^-[\p{Nd}]+$|^-[\p{Nd}]*\.[\p{Nd}]+$/u;

class Action {
  constructor({
    optionStrings,
    dest,
    nargs = null,
    required = false,
    help = null,
    type = null,
    defaultValue = null,
    kind = 'store',
  }) {
    this.optionStrings = optionStrings;
    this.dest = dest;
    this.nargs = nargs;
    this.required = required;
    this.help = help;
    this.type = type;
    this.defaultValue = defaultValue;
    this.kind = kind;
  }

  /** `_get_action_name`: how the action is named in error messages. */
  get name() {
    return this.optionStrings.length > 0
      ? this.optionStrings.join('/')
      : this.dest;
  }
}

export class ArgumentParser {
  constructor({ prog, addHelp = true } = {}) {
    this.prog = prog;
    this.prefixChars = '-';
    this.actions = [];
    // Insertion order drives abbreviation-ambiguity message ordering.
    this.optionStringActions = new Map();
    if (addHelp) {
      this.addArgument(['-h', '--help'], {
        nargs: 0,
        kind: 'help',
        dest: 'help',
        help: 'show this help message and exit',
      });
    }
  }

  addArgument(optionStrings, options = {}) {
    const dest = options.dest ?? deriveDest(optionStrings);
    const action = new Action({ ...options, optionStrings, dest });
    this.actions.push(action);
    for (const optionString of optionStrings) {
      this.optionStringActions.set(optionString, action);
    }
    return action;
  }

  #formatter() {
    const formatter = new HelpFormatter(this.prog);
    formatter.measureActions(this.actions);
    return formatter;
  }

  formatUsage() {
    const formatter = this.#formatter();
    return HelpFormatter.normalize(formatter.formatUsage(this.actions));
  }

  formatHelp() {
    const formatter = this.#formatter();
    const optionals = this.actions.filter((a) => a.optionStrings.length > 0);
    const positionals = this.actions.filter((a) => a.optionStrings.length === 0);
    let help = formatter.formatUsage(this.actions);
    help += formatter.formatSection('positional arguments', positionals);
    help += formatter.formatSection('options', optionals);
    return HelpFormatter.normalize(help);
  }

  printHelp() {
    writeStdout(this.formatHelp());
  }

  /** `parser.error()`: usage plus message on stderr, exit status 2. */
  error(message) {
    writeStderr(this.formatUsage());
    writeStderr(`${this.prog}: error: ${message}\n`);
    process.exit(2);
  }

  parseArgs(args = process.argv.slice(2)) {
    const [namespace, extras] = this.parseKnownArgs(args);
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return namespace;
  }

  parseKnownArgs(args) {
    const namespace = {};
    for (const action of this.actions) {
      if (action.kind !== 'help') namespace[action.dest] = action.defaultValue;
    }

    // Classify every argument up front: 'O' option, 'A' value, '-' bare '--'.
    const pattern = [];
    const optionTuples = new Map();
    for (let i = 0; i < args.length; i += 1) {
      if (args[i] === '--') {
        pattern.push('-');
        for (let j = i + 1; j < args.length; j += 1) pattern.push('A');
        break;
      }
      const tuple = this.#parseOptional(args[i]);
      if (tuple === null) {
        pattern.push('A');
      } else {
        optionTuples.set(i, tuple);
        pattern.push('O');
      }
    }

    const seen = new Set();
    const extras = [];
    let index = 0;
    while (index < args.length) {
      const tuple = optionTuples.get(index);
      if (tuple === undefined) {
        // No positionals are defined, so anything left over is an extra.
        extras.push(args[index]);
        index += 1;
        continue;
      }
      try {
        index = this.#consumeOptional(index, args, pattern, tuple, namespace, seen, extras);
      } catch (err) {
        if (!(err instanceof ArgumentError)) throw err;
        this.error(`argument ${err.action.name}: ${err.argumentMessage}`);
      }
    }

    // Required options are reported before unrecognized arguments.
    const missing = this.actions
      .filter((action) => action.required && !seen.has(action))
      .map((action) => action.name);
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    return [namespace, extras];
  }

  /** `_parse_optional`: resolve to [action, optionString, sep, explicitArg]. */
  #parseOptional(argString) {
    if (argString === '') return null;
    if (!this.prefixChars.includes(argString[0])) return null;
    if (this.optionStringActions.has(argString)) {
      return [this.optionStringActions.get(argString), argString, null, null];
    }
    if (argString.length === 1) return null;

    const equals = argString.indexOf('=');
    if (equals >= 0) {
      const optionString = argString.slice(0, equals);
      if (this.optionStringActions.has(optionString)) {
        return [
          this.optionStringActions.get(optionString),
          optionString,
          '=',
          argString.slice(equals + 1),
        ];
      }
    }

    const candidates = this.#optionTuples(argString);
    if (candidates.length > 1) {
      const options = candidates.map((tuple) => tuple[1]).join(', ');
      this.error(`ambiguous option: ${argString} could match ${options}`);
    }
    if (candidates.length === 1) return candidates[0];

    // Nothing in the parser looks like a negative number, so '-3' is a value.
    if (NEGATIVE_NUMBER.test(argString)) return null;
    if (argString.includes(' ')) return null;
    return [null, argString, null, null];
  }

  /** `_get_option_tuples`: abbreviation and bundled-short-option candidates. */
  #optionTuples(argString) {
    const result = [];
    const chars = this.prefixChars;
    const isLong = argString.length > 1 &&
      chars.includes(argString[0]) && chars.includes(argString[1]);

    if (isLong) {
      let optionPrefix = argString;
      let sep = null;
      let explicitArg = null;
      const equals = argString.indexOf('=');
      if (equals >= 0) {
        optionPrefix = argString.slice(0, equals);
        sep = '=';
        explicitArg = argString.slice(equals + 1);
      }
      for (const [optionString, action] of this.optionStringActions) {
        if (optionString.startsWith(optionPrefix)) {
          result.push([action, optionString, sep, explicitArg]);
        }
      }
    } else {
      // A single-character option may carry its argument with no separator.
      const shortOptionPrefix = argString.slice(0, 2);
      const shortExplicitArg = argString.slice(2);
      for (const [optionString, action] of this.optionStringActions) {
        if (optionString === shortOptionPrefix) {
          result.push([action, optionString, '', shortExplicitArg]);
        } else if (optionString.startsWith(argString)) {
          result.push([action, optionString, null, null]);
        }
      }
    }
    return result;
  }

  /** `consume_optional`: returns the index to resume parsing from. */
  #consumeOptional(startIndex, args, pattern, optionTuple, namespace, seen, extras) {
    let [action, optionString, sep, explicitArg] = optionTuple;
    const pending = [];
    let stop = startIndex;

    for (;;) {
      if (action === null) {
        extras.push(args[startIndex]);
        return startIndex + 1;
      }
      if (explicitArg !== null) {
        const argCount = action.nargs === 0 ? 0 : 1;
        if (
          argCount === 0 &&
          !this.prefixChars.includes(optionString[1]) &&
          explicitArg !== ''
        ) {
          // '-hfoo' means '-h -f -o -o': a flag written as a single-dash
          // option absorbs the tail as further short options. An explicit
          // separator ('-h=x') or a dash-led tail ('-h-x') is an error instead.
          if (sep !== '' || this.prefixChars.includes(explicitArg[0])) {
            throw new ArgumentError(
              action,
              `ignored explicit argument ${pyReprStr(explicitArg)}`,
            );
          }
          pending.push([action, [], optionString]);
          const char = optionString[0];
          const bundled = char + explicitArg[0];
          if (!this.optionStringActions.has(bundled)) {
            extras.push(char + explicitArg);
            stop = startIndex + 1;
            break;
          }
          action = this.optionStringActions.get(bundled);
          optionString = bundled;
          const rest = explicitArg.slice(1);
          if (rest === '') {
            sep = null;
            explicitArg = null;
          } else if (rest[0] === '=') {
            sep = '=';
            explicitArg = rest.slice(1);
          } else {
            sep = '';
            explicitArg = rest;
          }
          continue;
        }
        if (argCount === 1) {
          stop = startIndex + 1;
          pending.push([action, [explicitArg], optionString]);
          break;
        }
        throw new ArgumentError(
          action,
          `ignored explicit argument ${pyReprStr(explicitArg)}`,
        );
      }

      // For optionals argparse strips the dash allowances from the nargs
      // pattern, so the very next argument must be a plain value.
      const valueStart = startIndex + 1;
      if (action.nargs === 0) {
        stop = valueStart;
        pending.push([action, [], optionString]);
        break;
      }
      if (pattern[valueStart] !== 'A') {
        throw new ArgumentError(action, 'expected one argument');
      }
      stop = valueStart + 1;
      pending.push([action, [args[valueStart]], optionString]);
      break;
    }

    for (const [act, values, optStr] of pending) {
      this.#takeAction(act, values, optStr, namespace, seen);
    }
    return stop;
  }

  #takeAction(action, values, optionString, namespace, seen) {
    seen.add(action);
    if (action.kind === 'help') {
      this.printHelp();
      process.exit(0);
    }
    let value = values.length > 0 ? values[0] : null;
    if (action.type !== null && value !== null) {
      value = action.type(value, action, optionString, this);
    }
    namespace[action.dest] = value;
  }
}

function deriveDest(optionStrings) {
  const long = optionStrings.find((s) => s.startsWith('--'));
  const chosen = long ?? optionStrings[0];
  return chosen.replace(/^-+/, '').replace(/-/g, '_');
}
